<template>
	<view class="search-page">
		<view class="search-header" :style="{ paddingTop: statusBarHeight + 'px' }">
			<view class="header-row">
				<view class="back-button" @click="goBack"><text class="back-arrow"></text></view>
				<view class="search-input-wrap">
					<text class="search-symbol"></text>
					<input
						v-model="keyword"
						class="search-input"
						placeholder="搜索动态、话题或用户"
						placeholder-class="search-placeholder"
						confirm-type="search"
						:focus="true"
						@input="handleInput"
						@confirm="submitSearch"
					/>
					<view v-if="keyword" class="clear-button" @click="clearKeyword">×</view>
				</view>
				<text class="search-action" @click="submitSearch">搜索</text>
			</view>
		</view>

		<view :style="{ height: headerHeight + 'px' }"></view>

		<view v-if="!hasSearched" class="discovery-panel">
			<view v-if="history.length" class="history-head">
				<text class="section-title">最近搜索</text>
				<text class="clear-history" @click="clearHistory">清空</text>
			</view>
			<view v-if="history.length" class="history-list">
				<view v-for="item in history" :key="item" class="history-chip" @click="useHistory(item)">{{ item }}</view>
			</view>
			<view v-else class="initial-empty">
				<text class="initial-title">寻找同频内容</text>
				<text class="initial-copy">输入昵称、城市、动态关键词或话题名称</text>
			</view>
		</view>

		<view v-else class="result-area" :style="{ height: resultHeight + 'px' }">
			<scroll-view class="tab-scroll" scroll-x :show-scrollbar="false">
				<view class="tabs">
					<view v-for="tab in tabs" :key="tab.value" class="tab" :class="{ active: activeTab === tab.value }" @click="switchTab(tab.value)">{{ tab.label }}</view>
				</view>
			</scroll-view>

			<scroll-view class="result-scroll" scroll-y enhanced :show-scrollbar="false" @scrolltolower="loadMore">
				<view v-if="loading && !hasAnyResult" class="loading-state">正在搜索...</view>

				<template v-if="activeTab === 'all'">
					<view v-if="results.users.length" class="result-section"><view class="result-section-head"><text class="result-section-title">相关用户</text><text class="result-section-count">{{ results.users.length }}</text></view>
						<view v-for="item in results.users" :key="item.id" class="user-result" @click="goUser(item.id)"><view class="avatar-wrap"><image class="result-avatar" :src="item.avatar || defaultAvatarUrl" mode="aspectFill" /><view class="avatar-status"></view></view><view class="result-main"><view class="user-name-row"><VipName class="result-title" :name="item.name" :is-member="item.isMember" /><view v-if="item.gender" class="user-gender-pill" :class="item.gender === '男' ? 'male' : 'female'">{{ item.gender === '男' ? '♂' : '♀' }}<text v-if="item.age"> {{ item.age }}</text></view></view><text class="result-meta">{{ item.city || '未知城市' }}</text><text v-if="item.intro" class="result-desc">{{ item.intro }}</text></view><text class="row-arrow">›</text></view>
					</view>
					<view v-if="results.capsules.length" class="result-section"><view class="result-section-head"><text class="result-section-title">相关动态</text><text class="result-section-count">{{ results.capsules.length }}</text></view>
						<view v-for="item in results.capsules" :key="item.id" class="capsule-result" @click="goDetail(item.id)"><view class="result-main"><text class="result-title capsule-title">{{ item.title || item.content }}</text><text class="result-desc capsule-desc">{{ item.content }}</text><view class="capsule-meta-row"><VipName class="result-meta" :name="item.authorName" :is-member="item.authorIsMember" /><text v-if="item.topicTitle" class="topic-chip"># {{ item.topicTitle }}</text></view></view><image v-if="item.coverUrl" class="result-cover" :src="item.coverUrl" mode="aspectFill" /></view>
					</view>
					<view v-if="results.topics.length" class="result-section"><view class="result-section-head"><text class="result-section-title">相关话题</text><text class="result-section-count">{{ results.topics.length }}</text></view>
						<view v-for="item in results.topics" :key="item.id" class="topic-result" @click="useTopic(item.title)"><view class="topic-mark">#</view><view class="result-main"><text class="result-title">{{ item.title }}</text><text v-if="item.description" class="result-desc">{{ item.description }}</text></view><text class="row-arrow">›</text></view>
					</view>
				</template>

				<view v-else class="single-list">
					<view v-for="item in activeTab === 'users' ? results.users : []" :key="item.id" class="user-result" @click="goUser(item.id)"><view class="avatar-wrap"><image class="result-avatar" :src="item.avatar || defaultAvatarUrl" mode="aspectFill" /><view class="avatar-status"></view></view><view class="result-main"><view class="user-name-row"><VipName class="result-title" :name="item.name" :is-member="item.isMember" /><view v-if="item.gender" class="user-gender-pill" :class="item.gender === '男' ? 'male' : 'female'">{{ item.gender === '男' ? '♂' : '♀' }}<text v-if="item.age"> {{ item.age }}</text></view></view><text class="result-meta">{{ item.city || '未知城市' }}</text><text v-if="item.intro" class="result-desc">{{ item.intro }}</text></view><text class="row-arrow">›</text></view>
					<view v-for="item in activeTab === 'capsules' ? results.capsules : []" :key="item.id" class="capsule-result" @click="goDetail(item.id)"><view class="result-main"><text class="result-title capsule-title">{{ item.title || item.content }}</text><text class="result-desc capsule-desc">{{ item.content }}</text><view class="capsule-meta-row"><VipName class="result-meta" :name="item.authorName" :is-member="item.authorIsMember" /><text v-if="item.topicTitle" class="topic-chip"># {{ item.topicTitle }}</text></view></view><image v-if="item.coverUrl" class="result-cover" :src="item.coverUrl" mode="aspectFill" /></view>
					<view v-for="item in activeTab === 'topics' ? results.topics : []" :key="item.id" class="topic-result" @click="useTopic(item.title)"><view class="topic-mark">#</view><view class="result-main"><text class="result-title">{{ item.title }}</text><text v-if="item.description" class="result-desc">{{ item.description }}</text></view><text class="row-arrow">›</text></view>
				</view>

				<view v-if="!loading && !hasAnyResult" class="empty-state">
					<image src="/static/empty.png" mode="aspectFit" />
					<text>没有找到与“{{ searchedKeyword }}”相关的内容</text>
				</view>
				<view v-if="loading && hasAnyResult" class="load-more">正在加载...</view>
				<view v-else-if="activeTab !== 'all' && hasAnyResult && !hasMore" class="load-more">已经到底了</view>
			</scroll-view>
		</view>
	</view>
</template>

<script>
import { searchContent } from '../../api/search';
import { showRequestError } from '../../utils/feedback';
import { DEFAULT_AVATAR_URL } from '../../config';
import * as profileGuard from '../../utils/profileGuard';
import VipName from '../../components/VipName.vue';

export default {
	components: { VipName },
	data() {
		return {
			statusBarHeight: 44,
			headerHeight: 100,
			resultHeight: 600,
			keyword: '',
			searchedKeyword: '',
			activeTab: 'all',
			tabs: [
				{ label: '全部', value: 'all' },
				{ label: '动态', value: 'capsules' },
				{ label: '用户', value: 'users' },
				{ label: '话题', value: 'topics' }
			],
			results: { capsules: [], users: [], topics: [] },
			page: 1,
			hasMore: false,
			loading: false,
			hasSearched: false,
			history: [],
			searchTimer: null,
			requestVersion: 0,
			defaultAvatarUrl: DEFAULT_AVATAR_URL
		};
	},
	computed: {
		hasAnyResult() {
			return this.results.capsules.length + this.results.users.length + this.results.topics.length > 0;
		}
	},
	onLoad() {
		const info = uni.getSystemInfoSync();
		this.statusBarHeight = info.statusBarHeight || 44;
		this.headerHeight = this.statusBarHeight + 56;
		this.resultHeight = Math.max(320, Number(info.windowHeight || 700) - this.headerHeight);
		this.loadHistory();
	},
	onUnload() { clearTimeout(this.searchTimer); },
	methods: {
		handleInput() {
			clearTimeout(this.searchTimer);
			if (!this.keyword.trim()) {
				this.hasSearched = false;
				this.results = { capsules: [], users: [], topics: [] };
				return;
			}
			this.searchTimer = setTimeout(() => this.runSearch(true), 350);
		},
		submitSearch() {
			clearTimeout(this.searchTimer);
			if (!this.keyword.trim()) {
				uni.showToast({ title: '请输入搜索内容', icon: 'none' });
				return;
			}
			this.runSearch(true);
		},
		async runSearch(reset = false) {
			if (this.loading && !reset) return;
			const query = this.keyword.trim();
			if (!query) return;
			if (reset) {
				this.page = 1;
				this.results = { capsules: [], users: [], topics: [] };
			}
			const version = ++this.requestVersion;
			this.loading = true;
			this.hasSearched = true;
			this.searchedKeyword = query;
			try {
				const result = await searchContent({ q: query, type: this.activeTab, page: this.page, pageSize: 20 });
				if (version !== this.requestVersion) return;
				for (const key of ['capsules', 'users', 'topics']) {
					const incoming = Array.isArray(result[key]) ? result[key] : [];
					this.results[key] = reset ? incoming : [...this.results[key], ...incoming];
				}
				this.hasMore = Boolean(result.hasMore);
				this.saveHistory(query);
			} catch (error) {
				if (version === this.requestVersion) showRequestError(error, '搜索失败');
			} finally {
				if (version === this.requestVersion) this.loading = false;
			}
		},
		switchTab(value) {
			if (value === this.activeTab) return;
			this.activeTab = value;
			this.runSearch(true);
		},
		loadMore() {
			if (this.activeTab === 'all' || !this.hasMore || this.loading) return;
			this.page += 1;
			this.runSearch(false);
		},
		useTopic(title) {
			this.keyword = title;
			this.activeTab = 'capsules';
			this.runSearch(true);
		},
		useHistory(value) { this.keyword = value; this.runSearch(true); },
		clearKeyword() {
			clearTimeout(this.searchTimer);
			this.keyword = '';
			this.hasSearched = false;
			this.results = { capsules: [], users: [], topics: [] };
		},
		loadHistory() {
			const stored = uni.getStorageSync('search_history');
			this.history = Array.isArray(stored) ? stored : [];
		},
		saveHistory(value) {
			this.history = [value, ...this.history.filter((item) => item !== value)].slice(0, 10);
			uni.setStorageSync('search_history', this.history);
		},
		clearHistory() { this.history = []; uni.removeStorageSync('search_history'); },
		formatUserMeta(item) { return [item.age ? `${item.age}岁` : '', item.city].filter(Boolean).join(' · '); },
		async goDetail(id) {
			if (!(await profileGuard.ensureProfileCompleted({ actionText: '查看详情' }))) return;
			uni.navigateTo({ url: `/pages/detail/index?id=${encodeURIComponent(id)}` });
		},
		async goUser(id) {
			if (!(await profileGuard.ensureProfileCompleted({ actionText: '查看主页' }))) return;
			uni.navigateTo({ url: `/pages/user/index?id=${encodeURIComponent(id)}` });
		},
		goBack() { uni.navigateBack(); }
	}
};
</script>

<style lang="scss" scoped>
.search-page { min-height: 100vh; background: linear-gradient(180deg, #fff9fc 0%, #f8f8fb 28%, #f7f8fb 100%); color: #292832; }
.search-header { position: fixed; z-index: 20; top: 0; left: 0; right: 0; background: rgba(255, 250, 253, .97); border-bottom: 1rpx solid #f1e9ef; }
.header-row { display: flex; align-items: center; gap: 14rpx; height: 112rpx; padding: 0 24rpx; box-sizing: border-box; }
.back-button { display: flex; align-items: center; justify-content: center; width: 56rpx; height: 56rpx; flex-shrink: 0; }
.back-arrow { width: 18rpx; height: 18rpx; border-left: 3rpx solid #55525d; border-bottom: 3rpx solid #55525d; transform: rotate(45deg); }
.search-input-wrap { display: flex; align-items: center; flex: 1; min-width: 0; height: 72rpx; padding: 0 22rpx; border: 1rpx solid #eee5ec; border-radius: 36rpx; background: #ffffff; box-shadow: 0 6rpx 18rpx rgba(130, 91, 112, .06); box-sizing: border-box; }
.search-symbol { width: 22rpx; height: 22rpx; margin-right: 14rpx; border: 3rpx solid #b1a9b2; border-radius: 50%; position: relative; flex-shrink: 0; }
.search-symbol::after { content: ''; position: absolute; width: 10rpx; height: 3rpx; right: -8rpx; bottom: -5rpx; background: #96939e; transform: rotate(45deg); }
.search-input { flex: 1; min-width: 0; height: 72rpx; color: #3a3740; font-size: 27rpx; }
.search-placeholder { color: #b5aeb7; }
.clear-button { display: flex; align-items: center; justify-content: center; width: 40rpx; height: 40rpx; color: #96939e; font-size: 36rpx; }
.search-action { color: #d4688a; font-size: 26rpx; font-weight: 500; flex-shrink: 0; }
.discovery-panel { padding: 34rpx 28rpx; }
.history-head { display: flex; align-items: center; justify-content: space-between; }
.section-title { font-size: 31rpx; font-weight: 600; }
.clear-history { color: #9c99a3; font-size: 24rpx; }
.history-list { display: flex; flex-wrap: wrap; gap: 18rpx; margin-top: 24rpx; }
.history-chip { max-width: 280rpx; padding: 14rpx 24rpx; overflow: hidden; border-radius: 8rpx; background: #fff; color: #55545e; font-size: 25rpx; text-overflow: ellipsis; white-space: nowrap; }
.initial-empty { padding: 150rpx 30rpx; text-align: center; }
.initial-title, .initial-copy { display: block; }
.initial-title { font-size: 31rpx; font-weight: 600; }
.initial-copy { margin-top: 18rpx; color: #aaa7b0; font-size: 25rpx; }
.result-area { display: flex; flex-direction: column; }
.tab-scroll { flex-shrink: 0; width: 100%; background: rgba(255,255,255,.92); border-bottom: 1rpx solid #f1edf1; white-space: nowrap; }
.tabs { display: inline-flex; justify-content: space-around; min-width: 100%; height: 82rpx; padding: 0 18rpx; box-sizing: border-box; }
.tab { display: flex; align-items: center; justify-content: center; min-width: 124rpx; height: 82rpx; color: #918b96; font-size: 26rpx; position: relative; }
.tab.active { color: #24242c; font-weight: 600; }
.tab.active::after { content: ''; position: absolute; left: 40rpx; right: 40rpx; bottom: 0; height: 5rpx; border-radius: 3rpx; background: linear-gradient(90deg, #f08db1, #df76a0); }
.result-scroll { flex: 1; min-height: 0; }
.result-section, .single-list { margin-top: 14rpx; padding: 0 28rpx; background: rgba(255,255,255,.96); }
.result-section-head { display: flex; align-items: center; gap: 10rpx; padding: 28rpx 0 12rpx; }
.result-section-title { color: #34313a; font-size: 28rpx; font-weight: 600; }
.result-section-count { display: flex; align-items: center; justify-content: center; min-width: 34rpx; height: 34rpx; padding: 0 8rpx; border-radius: 17rpx; background: #fff0f5; color: #db7399; font-size: 20rpx; box-sizing: border-box; }
.user-result, .capsule-result, .topic-result { display: flex; align-items: center; gap: 20rpx; min-height: 142rpx; padding: 22rpx 0; border-top: 1rpx solid #f1edf1; box-sizing: border-box; }
.result-section-title + .user-result, .result-section-title + .capsule-result, .result-section-title + .topic-result, .single-list > view:first-child { border-top: 0; }
.result-section-head + .user-result, .result-section-head + .capsule-result, .result-section-head + .topic-result { border-top: 0; }
.avatar-wrap { position: relative; width: 86rpx; height: 86rpx; flex-shrink: 0; }
.result-avatar { width: 86rpx; height: 86rpx; border: 3rpx solid #fff; border-radius: 50%; background: #eee; box-shadow: 0 3rpx 12rpx rgba(109, 80, 98, .14); box-sizing: border-box; }
.avatar-status { position: absolute; right: 1rpx; bottom: 3rpx; width: 18rpx; height: 18rpx; border: 3rpx solid #fff; border-radius: 50%; background: #78d9b0; box-sizing: border-box; }
.result-main { flex: 1; min-width: 0; }
.user-name-row, .capsule-meta-row { display: flex; align-items: center; gap: 10rpx; min-width: 0; }
.result-title, .result-desc, .result-meta { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.result-title { color: #2d2a32; font-size: 28rpx; font-weight: 600; }
.user-gender-pill { flex-shrink: 0; padding: 3rpx 10rpx; border-radius: 12rpx; font-size: 19rpx; }
.user-gender-pill.female { background: #fff0f6; color: #e0719b; }
.user-gender-pill.male { background: #eef5ff; color: #6a9fe8; }
.result-desc { margin-top: 9rpx; color: #696570; font-size: 24rpx; line-height: 1.45; }
.result-meta { margin-top: 8rpx; color: #aaa4ae; font-size: 22rpx; }
.row-arrow { color: #c8c2ca; font-size: 32rpx; flex-shrink: 0; }
.capsule-title { line-height: 1.4; }
.capsule-desc { display: -webkit-box; overflow: hidden; white-space: normal; text-overflow: ellipsis; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
.capsule-meta-row { margin-top: 12rpx; }
.capsule-meta-row .result-meta { margin-top: 0; }
.topic-chip { max-width: 220rpx; padding: 4rpx 12rpx; overflow: hidden; border-radius: 12rpx; background: #fff0f5; color: #d96f97; font-size: 20rpx; text-overflow: ellipsis; white-space: nowrap; }
.result-cover { width: 118rpx; height: 96rpx; border-radius: 8rpx; flex-shrink: 0; }
.topic-mark { display: flex; align-items: center; justify-content: center; width: 66rpx; height: 66rpx; border-radius: 16rpx; background: linear-gradient(145deg, #fff1f6, #fce8f1); color: #df6f98; font-size: 30rpx; font-weight: 600; flex-shrink: 0; }
.loading-state, .load-more { padding: 60rpx 0; color: #aaa7b0; text-align: center; font-size: 24rpx; }
.empty-state { display: flex; flex-direction: column; align-items: center; padding: 130rpx 30rpx; color: #9b98a2; font-size: 25rpx; text-align: center; }
.empty-state image { width: 180rpx; height: 180rpx; margin-bottom: 20rpx; }
</style>
